  "claims": [
    {
      "text": "Quantum machine learning can outperform classical algorithms on specific pattern-recognition and data-analysis tasks when quantum algorithms exploit coherence, entanglement, or quantum access models.",
      "short_title": "Quantum learning can accelerate analysis",
      "evidence_excerpts": [
        "Quantum speedup is defined by lower query or gate complexity for a quantum algorithm than for the corresponding classical algorithm."
      ]
    },
    {
      "text": "Quantum basic linear algebra subroutines provide exponential speedups for Fourier transforms, eigenvalue estimation, eigenvector finding, and linear equation solving relative to the best known classical counterparts.",
      "short_title": "qBLAS enables exponential speedups",
      "evidence_excerpts": [
        "The review identifies quantum Fourier transforms, eigenvector and eigenvalue routines, and linear-system solvers as qBLAS primitives with exponential speedups."
      ]
    },
    {
      "text": "Quantum principal component analysis can diagonalize a covariance-like density matrix and estimate principal components exponentially more efficiently than classical PCA when data are available in quantum form.",
      "short_title": "qPCA diagonalizes quantum covariance",
      "evidence_excerpts": [
        "qRAM maps classical vectors into quantum states, repeated sampling forms a density matrix proportional to covariance, and phase estimation extracts principal-component information."
      ]
    },
    {
      "text": "The HHL linear-system algorithm can output a quantum state proportional to a solution vector in polylogarithmic time under sparsity, conditioning, input-preparation, and readout assumptions.",
      "short_title": "HHL has conditional advantage",
      "evidence_excerpts": [
        "HHL takes O((log N)^2) quantum steps to output |x>, but full recovery of x can require many measurements and suitable state preparation."
      ]
    },
    {
      "text": "Large-scale quantum random access memory and quantum-state readout constraints can erase practical advantages for many linear-algebra-based quantum machine learning algorithms on classical data.",
      "short_title": "Input output bottlenecks dominate",
      "evidence_excerpts": [
        "Loading large classical data sets can require exponential time without qRAM, and reading full solution vectors or principal components can be exponentially hard."
      ]
    },
    {
      "text": "Circuit depth and implementation overhead can become prohibitive for nominally exponential quantum machine learning speedups without substantial algorithmic optimization and realistic cost estimates.",
      "short_title": "Overheads threaten practical speedups",
      "evidence_excerpts": [
        "One proposed realization of HHL is described as ballooning to approximately 10^25 circuit-size and depth overhead before optimization."
      ]
    },
    {
      "text": "Deep quantum learning can use quantum annealers, programmable photonic circuits, and quantum Boltzmann machines rather than requiring a large universal quantum computer.",
      "short_title": "Special hardware supports deep learning",
      "evidence_excerpts": [
        "The review states that quantum annealers are easier to construct and scale than general-purpose quantum computers and are suited to deep quantum learners."
      ]
    },
    {
      "text": "Quantum Boltzmann machine training can gain quadratic improvements in thermalization, sampling, and training-data access under quantum-coherent or qRAM access assumptions.",
      "short_title": "Quantum Boltzmann training accelerates",
      "evidence_excerpts": [
        "Quantum methods can make Boltzmann systems thermalize quadratically faster and can quadratically reduce samples and training-data accesses."
      ]
    },
    {
      "text": "Quantum machine learning for quantum data can reduce tomography and characterization costs by extracting principal components, dynamics, or expectation-value summaries without full state reconstruction.",
      "short_title": "Quantum data avoids full tomography",
      "evidence_excerpts": [
        "Quantum analysis of density matrices can reveal principal components and dynamics with exponentially fewer measurements than full quantum state reconstruction."
      ]
    },
    {
      "text": "The near-term viability of quantum machine learning depends on solving input, output, costing, and benchmarking problems rather than only proving asymptotic speedups.",
      "short_title": "Viability needs practical benchmarks",
      "evidence_excerpts": [
        "The review distills four caveats for future work: input problem, output problem, costing problem, and benchmarking problem."
      ]
    }
  ],
  "evidence_items": [
    {
      "evidence_id": "evidence-speedup-resource-definition--a91f0184eb29",
      "title": "Quantum Speedup Resource Test",
      "excerpt": "Quantum speedup is evaluated through query complexity and gate complexity: a speedup exists when a quantum algorithm needs fewer information-source queries or fewer elementary operations than the classical alternative.",
      "overview": "This formal resource criterion grounds the review's claims about quantum machine learning advantages. It keeps the discussion tied to algorithmic costs rather than vague statements that quantum computers are faster, while also exposing why real-device benchmarking remains necessary.",
      "evidence_type": "formal_argument",
      "claim_refs": [
